// Verificación CDP: navega, espera, evalúa estado y captura screenshot
const { spawn } = require('child_process');
const fs = require('fs');

const CHROME = '/usr/bin/google-chrome';
const PORT = 9333;
const URL = 'file:///var/tmp/bench/ws-BJpkZXQb/alhambra-3d.html';

const chrome = spawn(CHROME, [
  '--headless=new', '--no-sandbox', '--remote-debugging-port=' + PORT,
  '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
  '--window-size=1400,900', 'about:blank'
], { stdio: ['ignore','ignore','pipe'] });
let chromeErr = '';
chrome.stderr.on('data', d => chromeErr += d);

const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  // esperar que el puerto devtools esté arriba
  let targets = null;
  for (let i = 0; i < 40; i++) {
    await sleep(250);
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json`);
      targets = await res.json();
      if (targets.length) break;
    } catch {}
  }
  if (!targets || !targets.length) { console.log('FAIL: no devtools target'); process.exit(1); }
  const ws = new WebSocket(targets[0].webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);

  let id = 0; const pend = new Map();
  ws.onmessage = e => {
    const m = JSON.parse(e.data);
    if (m.id && pend.has(m.id)) { pend.get(m.id)(m); pend.delete(m.id); }
  };
  const send = (method, params={}) => new Promise(res => {
    const mid = ++id; pend.set(mid, res);
    ws.send(JSON.stringify({ id: mid, method, params }));
  });

  await send('Page.enable');
  await send('Runtime.enable');
  const nav = await send('Page.navigate', { url: URL });
  if (nav.result && nav.result.errorText) console.log('nav error:', nav.result.errorText);

  await sleep(8000); // tiempo real: carga CDN + construcción + frames rAF

  const ev = async expr => {
    const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
    return r.result && r.result.result ? r.result.result.value : undefined;
  };

  const loadingGone = await ev(`document.getElementById('loading') === null`);
  const canvasCount = await ev(`document.querySelectorAll('canvas').length`);
  const canvasSize = await ev(`(() => { const c = document.querySelector('#app canvas'); return c ? c.width + 'x' + c.height : 'none'; })()`);
  const hasWebGL = await ev(`(() => { const c = document.querySelector('#app canvas'); return !!(c && c.getContext('webgl2') || c && c.getContext('webgl')); })()`);
  const glErr = await ev(`window.__glProbe === undefined ? 'no-probe' : window.__glProbe`);

  const shot = await send('Page.captureScreenshot', { format: 'png' });
  if (shot.result && shot.result.data) {
    fs.writeFileSync('/tmp/opencode/alhambra_cdp.png', Buffer.from(shot.result.data, 'base64'));
    console.log('screenshot saved');
  } else console.log('no screenshot', JSON.stringify(shot).slice(0,200));

  console.log({ loadingGone, canvasCount, canvasSize, hasWebGL });

  // análisis de píxeles
  try {
    const { execSync } = require('child_process');
    const out = execSync(`python3 - <<'PY'
from PIL import Image
im = Image.open('/tmp/opencode/alhambra_cdp.png').convert('RGB').resize((140,90))
px = list(im.getdata()); n = len(px)
from collections import Counter
c = Counter(px)
print('unique:', len(c))
for col,cnt in c.most_common(6): print(col, round(cnt/n*100,1),'%')
rows = {}
for i,p in enumerate(px):
    y = i//140
    rows.setdefault(y, []).append(p)
def avg(row): return tuple(round(sum(q[i] for q in row)/len(row)) for i in range(3))
print('fila 0 (cielo):', avg(rows[0]))
print('fila 45:', avg(rows[45]))
print('fila 80 (suelo):', avg(rows[80]))
PY`).toString();
    console.log(out);
  } catch (e) { console.log('pix analysis fail'); }

  ws.close();
  chrome.kill();
  process.exit(0);
})().catch(e => { console.log('ERROR', e.message); chrome.kill(); process.exit(1); });

