  '--headless=new', '--no-sandbox', '--remote-debugging-port=' + PORT,
  '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
  '--window-size=1400,900', 'about:blank'
], { stdio: ['ignore','ignore','ignore'] });
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  let targets = null;
  for (let i = 0; i < 40; i++) {
    await sleep(250);
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json`);
      targets = await res.json();
      if (targets.length) break;
    } catch {}
  }
  const ws = new WebSocket(targets[0].webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);

  const logs = [];
  ws.onmessage = e => {
    const m = JSON.parse(e.data);
    if (m.method === 'Runtime.consoleAPICalled') {
      const txt = (m.params.args||[]).map(a => a.value !== undefined ? a.value : (a.description||a.type)).join(' ');
      logs.push(`[console:${m.params.type}] ${txt}`);
    }
    if (m.method === 'Runtime.exceptionThrown') {
      const d = m.params.exceptionDetails;
      logs.push(`[EXCEPTION] ${(d.exception && (d.exception.description||d.exception.value)) || d.text}\n  at ${d.stackTrace ? d.stackTrace.callFrames.slice(0,6).map(f=>f.functionName+'@'+f.url.split('/').pop()+':'+f.lineNumber).join(' <- ') : ''}`);
    }
    if (m.method === 'Log.entryAdded') logs.push(`[log:${m.params.entry.level}] ${m.params.entry.text}`);
  };

  let id = 0; const pend = new Map();
  const send = (method, params={}) => new Promise(res => {
    const mid = ++id; pend.set(mid, res);
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
  ws.onmessage = e => {
    const m = JSON.parse(e.data);
    if (m.id && pend.has(m.id)) { pend.get(m.id)(m); pend.delete(m.id); }
    if (m.method === 'Runtime.consoleAPICalled') {
      const txt = (m.params.args||[]).map(a => a.value !== undefined ? String(a.value) : (a.description||a.type)).join(' ');
      logs.push(`[console:${m.params.type}] ${txt}`);
    }
    if (m.method === 'Runtime.exceptionThrown') {
      const d = m.params.exceptionDetails;
      const st = d.stackTrace ? d.stackTrace.callFrames.slice(0,6).map(f=>`${f.functionName||'(anon)'}@${(f.url||'').split('/').pop()||'inline'}:${f.lineNumber}`).join(' <- ') : '';
      logs.push(`[EXCEPTION] ${(d.exception && (d.exception.description||d.exception.value)) || d.text}\n  calls: ${st}`);
    }
    if (m.method === 'Log.entryAdded') logs.push(`[log:${m.params.entry.level}] ${m.params.entry.text}`);
  };

  await send('Runtime.enable');
  await send('Page.enable');
  await send('Log.enable');
  await send('Emulation.setScriptExecutionDisabled', { isDisabled: false });
  await send('Page.navigate', { url: URL });

  for (let s = 1; s <= 12; s++) {
    await sleep(1000);
    const r = await send('Runtime.evaluate', { expression: `document.getElementById('loading')===null ? 'DONE' : 'RUNNING...'`, returnByValue: true });
    if (s % 3 === 0 || (r.result && r.result.result && r.result.result.value === 'DONE')) {
      console.log(`t=${s}s:`, r.result && r.result.result ? r.result.result.value : '?');
    }
    if (r.result && r.result.result && r.result.result.value === 'DONE') break;
  }

  const r2 = await send('Runtime.evaluate', { expression: `
    (() => { const c = document.querySelector('#app canvas');
      if (!c) return 'no canvas';
      const gl = c.getContext('webgl2');
      const info = gl ? gl.getError() : 'no-gl2';
      return 'canvas ' + c.width + 'x' + c.height + ' glError=' + info; })()
  `, returnByValue: true });
  console.log('probe:', r2.result && r2.result.result ? r2.result.result.value : '?');

  console.log('---- registros del navegador (' + logs.length + ') ----');
  for (const l of logs.slice(0, 40)) console.log(l);
  ws.close(); chrome.kill();
  process.exit(0);
})().catch(e => { console.log('ERROR', e.message); chrome.kill(); process.exit(1); });

