    controls.target.set(-15, 10, 4);
    controls.update();
  } else {
    legend.classList.remove('visible');
    setPlaying(true);
  }
}
btnTour.addEventListener('click', () => setMode(false));
btnFree.addEventListener('click', () => setMode(true));
showPOI.addEventListener('change', () => markerGroup.visible = showPOI.checked);

function showPanel(p){
  if (!p){ panel.classList.remove('visible'); return; }
  infoNum.textContent = p.n;
  infoTitle.textContent = p.t;
  infoText.textContent = p.d;
  panel.classList.add('visible');
}
document.getElementById('infoClose').addEventListener('click', () => showPanel(null));

/* Detección de POI cercano durante la ruta */
let currentPOI = null;
function poiProximity(){
  let best = null, bestD = 1e9;
  for(const p of POIS){
    const d = (p.x-camera.position.x)**2 + (p.y-camera.position.y)**2 + (p.z-camera.position.z)**2;
    if (d < bestD){ bestD = d; best = p; }
  }
  const near = bestD < 169 ? best : null;
  if (near !== currentPOI){ currentPOI = near; showPanel(near); }
}

/* Clic sobre marcadores (modo libre) */
const raycaster = new THREE.Raycaster();
const pointer = new THREE.Vector2();
let downXY = null;
renderer.domElement.addEventListener('pointerdown', e => downXY = [e.clientX, e.clientY]);
renderer.domElement.addEventListener('pointerup', e => {
  if (!downXY) return;
  const moved = Math.hypot(e.clientX-downXY[0], e.clientY-downXY[1]);
  downXY = null;
  if (moved > 6) return;
  pointer.x = (e.clientX/innerWidth)*2 - 1;
  pointer.y = -(e.clientY/innerHeight)*2 + 1;
  raycaster.setFromCamera(pointer, camera);
  const hits = raycaster.intersectObjects(markerGroup.children, false);
  if (hits.length) showPanel(hits[0].object.userData.poi);
});

/* ============================================================
   ANIMACIÓN
============================================================ */
const clock = new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);

  if (!freeMode){
    if (playing){
      tourT += dt * baseRate * speed;
      if (tourT >= 1) tourT -= 1;
    }
    placeOnPath(tourT);
    poiProximity();
  } else {
    controls.update();
  }

  fill.style.width = (tourT*100).toFixed(2) + '%';
  mat.water.map.offset.x += dt * 0.045;
  mat.water.map.offset.y += dt * 0.012;

  renderer.render(scene, camera);
}

addEventListener('resize', () => {
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

/* Arranque */
markerGroup.visible = showPOI.checked;
setMode(false);
tourT = 0;
placeOnPath(0);
animate();
const load = document.getElementById('loading');
load.style.opacity = '0';
setTimeout(() => load.remove(), 900);

